CREATE DATABASE IF NOT EXISTS mensify_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mensify_db;
CREATE TABLE IF NOT EXISTS products (id VARCHAR(80) PRIMARY KEY, name VARCHAR(180) NOT NULL, brand VARCHAR(100) NOT NULL DEFAULT '', category VARCHAR(50) NOT NULL, category_name VARCHAR(80) NOT NULL DEFAULT '', description TEXT, price DECIMAL(10,2) NOT NULL DEFAULT 0, discount TINYINT UNSIGNED NOT NULL DEFAULT 0, stock INT NOT NULL DEFAULT 0, sku VARCHAR(100), image_url TEXT, images JSON, sizes JSON, colors JSON, tags JSON, rating DECIMAL(2,1) NOT NULL DEFAULT 0, reviews_count INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id VARCHAR(80) PRIMARY KEY, full_name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, phone VARCHAR(40), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(100) PRIMARY KEY, customer_id VARCHAR(80), customer_json JSON NOT NULL, items_json JSON NOT NULL, subtotal DECIMAL(10,2) NOT NULL, shipping DECIMAL(10,2) NOT NULL DEFAULT 0, tax DECIMAL(10,2) NOT NULL DEFAULT 0, total DECIMAL(10,2) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'Pending', payment_method VARCHAR(40), maya_checkout_id VARCHAR(160), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(customer_id), INDEX(status));
CREATE TABLE IF NOT EXISTS order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id VARCHAR(100) NOT NULL, product_id VARCHAR(80) NOT NULL, product_name VARCHAR(180) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, selected_size VARCHAR(30), selected_color VARCHAR(50), FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS contact_messages (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160), email VARCHAR(190), subject VARCHAR(255), message TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
